// Code node: "Validate & Count Days" (Run Once for All Items)
const toDate = (s) => {
  const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])) : null;
};
const iso = (d) => d.toISOString().slice(0, 10);
const rand = () => Math.random().toString(36).slice(2, 8).toUpperCase();

const out = [];
for (const item of $input.all()) {
  const f = item.json;
  let start = toDate(f['Start Date']);
  let end = toDate(f['End Date']) || start;
  if (start && end && end < start) [start, end] = [end, start];

  // Working days (Mon–Fri), inclusive
  let days = 0;
  if (start && end) {
    for (let d = new Date(start); d <= end; d.setUTCDate(d.getUTCDate() + 1)) {
      const wd = d.getUTCDay();
      if (wd !== 0 && wd !== 6) days++;
    }
  }

  out.push({
    json: {
      id: 'LV-' + rand(),
      submittedAt: new Date().toISOString(),
      name: String(f['Full Name'] || '').trim(),
      email: String(f['Work Email'] || '').trim().toLowerCase(),
      team: f['Team'] || '',
      type: f['Leave Type'] || 'Annual leave',
      start: start ? iso(start) : '',
      end: end ? iso(end) : '',
      days,
      reason: String(f['Reason'] || '').trim(),
      cover: String(f['Who covers your work?'] || '').trim(),
      status: 'Pending',
      decidedAt: null,
    },
  });
}
return out;

// Code node: "Save Request" (Run Once for All Items)
const store = $getWorkflowStaticData('global');
store.requests = store.requests || [];
for (const item of $input.all()) store.requests.unshift(item.json);
store.requests = store.requests.slice(0, 1000);
return $input.all();

// Code node: "Build Approvals Page" (Run Once for All Items)
const ACTION_URL = '/webhook/leave-action-CHANGE-ME-2';
const ANNUAL_ALLOWANCE = 14; // working days per calendar year

const store = $getWorkflowStaticData('global');
const reqs = store.requests || [];
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const today = new Date().toISOString().slice(0, 10);
const year = today.slice(0, 4);
const q = $input.first().json.query || {};
const flash = q.done ? String(q.done) : '';

// Annual leave used per person this year (approved only)
const used = {};
for (const r of reqs) {
  if (r.status === 'Approved' && r.type === 'Annual leave' && String(r.start).startsWith(year)) {
    used[r.email] = (used[r.email] || 0) + (r.days || 0);
  }
}
const left = (email) => ANNUAL_ALLOWANCE - (used[email] || 0);

// Who is off in the next 7 days
const in7 = new Date(Date.now() + 7 * 864e5).toISOString().slice(0, 10);
const upcoming = reqs
  .filter((r) => r.status === 'Approved' && r.end >= today && r.start <= in7)
  .sort((a, b) => a.start.localeCompare(b.start));
const offToday = reqs.filter((r) => r.status === 'Approved' && r.start <= today && r.end >= today);

const pending = reqs.filter((r) => r.status === 'Pending');
const decided = reqs.filter((r) => r.status !== 'Pending').slice(0, 25);

const fmtRange = (r) => (r.start === r.end ? r.start : `${r.start} → ${r.end}`);
const btn = (r, action, label, cls) =>
  `<form method="POST" action="${ACTION_URL}" style="display:inline"><input type="hidden" name="id" value="${esc(r.id)}"><input type="hidden" name="action" value="${action}"><button class="${cls}">${label}</button></form>`;

const pendingRows = pending
  .map((r) => {
    const over = r.type === 'Annual leave' && r.days > left(r.email);
    return `<tr>
<td><strong>${esc(r.name)}</strong><br><span class="muted">${esc(r.team)} · ${esc(r.email)}</span></td>
<td>${esc(r.type)}</td>
<td>${esc(fmtRange(r))}<br><span class="muted">${r.days} working day${r.days === 1 ? '' : 's'}</span></td>
<td>${r.type === 'Annual leave' ? `${left(r.email)} left${over ? ' <span class="warn">exceeds balance</span>' : ''}` : '<span class="muted">n/a</span>'}</td>
<td>${esc(r.reason) || '<span class="muted">—</span>'}${r.cover ? `<br><span class="muted">Cover: ${esc(r.cover)}</span>` : ''}</td>
<td class="actions">${btn(r, 'approve', 'Approve', 'ok')} ${btn(r, 'reject', 'Reject', 'no')}</td>
</tr>`;
  })
  .join('');

const decidedRows = decided
  .map(
    (r) => `<tr><td>${esc(r.name)}<br><span class="muted">${esc(r.team)}</span></td><td>${esc(r.type)}</td><td>${esc(fmtRange(r))} · ${r.days}d</td>
<td><span class="tag ${r.status === 'Approved' ? 'ok' : 'no'}">${esc(r.status)}</span></td><td class="muted">${esc((r.decidedAt || '').slice(0, 16).replace('T', ' '))}</td></tr>`
  )
  .join('');

const upcomingList = upcoming.map((r) => `<li><strong>${esc(r.name)}</strong> <span class="muted">(${esc(r.team)})</span> — ${esc(r.type)}, ${esc(fmtRange(r))}</li>`).join('');

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Leave Approvals</title>
<style>
:root{--bg:#f6f7f9;--card:#fff;--ink:#16181d;--muted:#6b7280;--line:#e5e7eb;--ok:#16a34a;--no:#dc2626;--warn:#d97706;--accent:#4f46e5}
@media (prefers-color-scheme:dark){:root{--bg:#0f1115;--card:#171a21;--ink:#e8eaed;--muted:#9aa1ad;--line:#2a2f3a}}
*{box-sizing:border-box}body{margin:0;font:14px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--ink)}
main{max-width:1150px;margin:0 auto;padding:24px 16px}h1{font-size:22px;margin:0 0 4px}h2{font-size:16px;margin:24px 0 10px}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:18px 0}
.kpi{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px}.kpi b{display:block;font-size:22px}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;overflow-x:auto}
table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:10px 12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
th{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}.muted{color:var(--muted);font-size:12px}
button{border:0;border-radius:8px;padding:7px 12px;font-weight:600;cursor:pointer;color:#fff}button.ok{background:var(--ok)}button.no{background:var(--no)}
.actions{white-space:nowrap}.tag{padding:2px 8px;border-radius:999px;font-size:12px;font-weight:600;color:#fff}.tag.ok{background:var(--ok)}.tag.no{background:var(--no)}
.warn{color:var(--warn);font-size:12px;font-weight:600}.empty{padding:24px;text-align:center;color:var(--muted)}
.flash{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;margin-top:12px}
ul{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 12px 12px 30px;margin:0}li{margin:4px 0}
</style></head><body><main>
<h1>Leave Approvals</h1><div class="muted">Team leave requests · annual allowance ${ANNUAL_ALLOWANCE} working days · ${esc(today)}</div>
${flash ? `<div class="flash">${esc(flash)}</div>` : ''}
<section class="kpis">
<div class="kpi"><span class="muted">Pending</span><b style="color:var(--warn)">${pending.length}</b></div>
<div class="kpi"><span class="muted">Off today</span><b>${offToday.length}</b></div>
<div class="kpi"><span class="muted">Approved (${year})</span><b style="color:var(--ok)">${reqs.filter((r) => r.status === 'Approved' && String(r.start).startsWith(year)).length}</b></div>
<div class="kpi"><span class="muted">Days approved (${year})</span><b>${reqs.filter((r) => r.status === 'Approved' && String(r.start).startsWith(year)).reduce((s, r) => s + r.days, 0)}</b></div>
</section>
<h2>Waiting for approval</h2>
<div class="card">${pending.length ? `<table><thead><tr><th>Employee</th><th>Type</th><th>Dates</th><th>Annual balance</th><th>Reason</th><th></th></tr></thead><tbody>${pendingRows}</tbody></table>` : '<div class="empty">No pending requests.</div>'}</div>
<h2>Who's off in the next 7 days</h2>
${upcomingList ? `<ul>${upcomingList}</ul>` : '<div class="card"><div class="empty">Nobody is scheduled to be off.</div></div>'}
<h2>Recent decisions</h2>
<div class="card">${decided.length ? `<table><thead><tr><th>Employee</th><th>Type</th><th>Dates</th><th>Status</th><th>Decided (UTC)</th></tr></thead><tbody>${decidedRows}</tbody></table>` : '<div class="empty">No decisions yet.</div>'}</div>
</main></body></html>`;

return [{ json: { html } }];

// Code node: "Apply Decision" (Run Once for All Items)
const ADMIN_URL = '/webhook/leave-admin-CHANGE-ME-2';
const store = $getWorkflowStaticData('global');
store.requests = store.requests || [];

const body = $input.first().json.body || {};
const id = String(body.id || '');
const action = String(body.action || '');
const r = store.requests.find((x) => x.id === id);

let message = 'Request not found.';
if (r && r.status === 'Pending' && (action === 'approve' || action === 'reject')) {
  r.status = action === 'approve' ? 'Approved' : 'Rejected';
  r.decidedAt = new Date().toISOString();
  message = `${r.name}'s ${r.type.toLowerCase()} (${r.start}${r.start === r.end ? '' : ' → ' + r.end}) was ${r.status.toLowerCase()}.`;
} else if (r) {
  message = `${r.id} was already ${r.status.toLowerCase()}.`;
}
return [{ json: { redirect: `${ADMIN_URL}?done=${encodeURIComponent(message)}`, id, action, message } }];
